class Solution {
public:
    int go(vector<int>& cnt) {
        int total = 0;
        for (int i = 0; i < 26; i++) {
            if (cnt[i] == 0) continue;
            total++;
            cnt[i]--;
            total += go(cnt);
            cnt[i]++;
        }
        return total;
    }
    int numTilePossibilities(string tiles) {
        vector<int> cnt(26, 0);
        for (char c : tiles) cnt[c - 'A']++;
        return go(cnt);
    }
};
